1	import {
2	  animateParallel,
3	  Block,
4	  InputFocusScrollView,
5	  Text,
6	  useForm,
7	} from "@prototyp/skeletor";
8	import type { NativeStackScreenProps } from "@react-navigation/native-stack";
9	import { useAtomValue } from "jotai";
10	import { AuthService } from "modules/auth/service/AuthService";
11	import { NetworkAtoms } from "modules/network/jotai";
12	import { VerificationService } from "modules/verification/service/VerificationService";
13	import type React from "react";
14	import { useEffect, useRef, useState } from "react";
15	import { Image, StyleSheet } from "react-native";
16	import Toast from "react-native-toast-message";
17	import {
18	  Button,
19	  GoBackHeader,
20	  Input,
21	  Loading,
22	  ScreenLayout,
23	} from "shared/components";
24	import { MOCKED_AUTH_DATA } from "shared/const/mocked-auth-data";
25	import { useNavigateToCorrectScreenHelper } from "shared/hooks";
26	import { Colors, TextSize } from "shared/styles";
27	import { offlineToastHelper } from "shared/utils";
28	
29	type FormState = {
30	  username: string;
31	  password: string;
32	};
33	
34	const animateUsername = animateParallel(
35	  {
36	    opacity: [0, 1],
37	    translateY: [-20, 0],
38	  },
39	  { duration: 200, native: false },
40	);
41	
42	const animatePassword = animateParallel(
43	  {
44	    opacity: [0, 1],
45	    translateY: [-20, 0],
46	  },
47	  { duration: 200, native: false },
48	);
49	
50	export const Login: React.FC<NativeStackScreenProps<Routes, "login">> = ({
51	  navigation,
52	}) => {
53	  const [loading, setLoading] = useState(false);
54	  const [passwordVisible, setPasswordVisible] = useState(false);
55	  const form = useForm<FormState>({
56	    username: MOCKED_AUTH_DATA("stjepan").username,
57	    password: MOCKED_AUTH_DATA("stjepan").password,
58	  });
59	  const isOffline = useAtomValue(NetworkAtoms.isOffline);
60	  const cancelledRef = useRef(false);
61	  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
62	
63	  const navigateToCorrectScreen = useNavigateToCorrectScreenHelper();
64	
65	  const handleCancel = async () => {
66	    cancelledRef.current = true;
67	    if (timeoutRef.current) clearTimeout(timeoutRef.current);
68	    setLoading(false);
69	    try {
70	      await AuthService.logout();
71	    } catch {}
72	    offlineToastHelper(
73	      "Something went wrong.",
74	      "Please try again or come back later.",
75	    );
76	  };
77	
78	  const submit = async () => {
79	    try {
80	      if (!form.validateForm()) return;
81	      if (isOffline) {
82	        offlineToastHelper("No internet connection");
83	        return;
84	      }
85	
86	      cancelledRef.current = false;
87	      setLoading(true);
88	      // If the user doesn't login in 30 seconds, cancel the login and show a toast.
89	      timeoutRef.current = setTimeout(() => handleCancel(), 30000);
90	
91	      const session = await AuthService.login(form.state);
92	      if (cancelledRef.current) return;
93	
94	      await AuthService.setup(session);
95	      if (cancelledRef.current) return;
96	
97	      Toast.show({
98	        type: "success",
99	        text1: "Successfully signed in",
100	      });
101	
102	      const isVerified = VerificationService.isDeviceVerified();
103	
104	      if (!isVerified) navigation.replace("confirmIdentity");
105	      else navigateToCorrectScreen();
106	    } catch (e: unknown) {
107	      if (cancelledRef.current) return;
108	
109	      console.error("Failed to authenticate properly: ", e);
110	
111	      const error = e as { inner?: { kind?: { tag?: string } } };
112	      const isRateLimited = error?.inner?.kind?.tag === "LimitExceeded";
113	
114	      offlineToastHelper(
115	        isRateLimited ? "Too many login attempts" : "Failed to login",
116	        isRateLimited
117	          ? "Please wait a moment and try again"
118	          : "Username or password is incorrect",
119	      );
120	    } finally {
121	      if (!cancelledRef.current) {
122	        if (timeoutRef.current) clearTimeout(timeoutRef.current);
123	        setLoading(false);
124	      }
125	    }
126	  };
127	
128	  useEffect(() => {
129	    if (form.state.username) animateUsername.start();
130	    else animateUsername.reverse();
131	  }, [form.state.username]);
132	
133	  useEffect(() => {
134	    if (form.state.password) animatePassword.start();
135	    else animatePassword.reverse();
136	  }, [form.state.password]);
137	
138	  return (
139	    <ScreenLayout>
140	      {loading && <Loading text="Signing in and syncing..." />}
141	      <InputFocusScrollView>
142	        {(focus) => (
143	          <Block flex={1}>
144	            <GoBackHeader />
145	            <Block gap={8} margins={{ marginBottom: 40 }}>
146	              <Text font="InstrumentSans-Medium" size={TextSize.large}>
147	                Sign in
148	              </Text>
149	              <Text
150	                color={Colors.white80}
151	                font="InstrumentSans-Regular"
152	                size={TextSize.base}
153	              >
154	                Enter your details to sign in.
155	              </Text>
156	            </Block>
157	
158	            <Block gap={8} margins={{ marginBottom: 32 }}>
159	              <Text
160	                style={animateUsername.animations}
161	                size={TextSize.tiny}
162	                color={Colors.white50}
163	                paddings={[0, 16]}
164	              >
165	                Username
166	              </Text>
167	              <Input
168	                placeholder="Username"
169	                value={form.state.username}
170	                keyboardType="email-address"
171	                autoCapitalize="none"
172	                onFocus={focus}
173	                onBlur={() => form.validate("username")}
174	                onChangeText={(value) => form.update("username", value)}
175	              />
176	              <Text
177	                color="red"
178	                opacity={form.validation.username === false ? 1 : 0}
179	                size={TextSize.tiny}
180	                paddings={[0, 16]}
181	                absolute
182	                offsets={{ bottom: -20 }}
183	              >
184	                Please enter a valid username.
185	              </Text>
186	            </Block>
187	
188	            <Block gap={8}>
189	              <Text
190	                style={animatePassword.animations}
191	                size={TextSize.tiny}
192	                color={Colors.white50}
193	                paddings={[0, 16]}
194	              >
195	                Password
196	              </Text>
197	              <Input
198	                placeholder="Password"
199	                secureTextEntry={!passwordVisible}
200	                value={form.state.password}
201	                onFocus={focus}
202	                onBlur={() => form.validate("password")}
203	                onChangeText={(value) => form.update("password", value)}
204	                onSubmitEditing={submit}
205	                rightIcon={
206	                  <Button.Wrapper
207	                    onPress={() => setPasswordVisible((prev) => !prev)}
208	                    hitSlop={8}
209	                    style={styles.passwordVisibleIconContainer}
210	                  >
211	                    <Image
212	                      source={
213	                        passwordVisible
214	                          ? require("assets/icons/eye.png")
215	                          : require("assets/icons/eye-slash.png")
216	                      }
217	                      style={styles.passwordVisibleIcon}
218	                    />
219	                  </Button.Wrapper>
220	                }
221	              />
222	              <Text
223	                color="red"
224	                opacity={form.validation.password === false ? 1 : 0}
225	                size={TextSize.tiny}
226	                paddings={[0, 16]}
227	                absolute
228	                offsets={{ bottom: -20 }}
229	              >
230	                Please enter a valid password.
231	              </Text>
232	            </Block>
233	          </Block>
234	        )}
235	      </InputFocusScrollView>
236	      <Block
237	        paddings={{ padding: 20 }}
238	        gap={12}
239	        justify="flex-end"
240	        minHeight={200}
241	      >
242	        <Button.Primary disabled={loading} onPress={submit}>
243	          Continue
244	        </Button.Primary>
245	      </Block>
