11	  constructor() {
12	    this.mmkv = minimalMMKVStorage;
13	  }
14	
15	  saveLoginCredentials = (credentials: {
16	    accessToken: string;
17	    refreshToken?: string;
18	    userId: string;
19	    deviceId: string;
20	    baseUrl: string;
21	  }) => {
22	    this.mmkv.set(SecureStoreKeys.MATRIX_ACCESS_TOKEN, credentials.accessToken);
23	    this.mmkv.set(SecureStoreKeys.MATRIX_USER_ID, credentials.userId);
24	    this.mmkv.set(SecureStoreKeys.MATRIX_DEVICE_ID, credentials.deviceId);
25	    this.mmkv.set(SecureStoreKeys.MATRIX_BASE_URL, credentials.baseUrl);
26	
27	    if (credentials.refreshToken) {
28	      this.mmkv.set(
29	        SecureStoreKeys.MATRIX_REFRESH_TOKEN,
30	        credentials.refreshToken,
31	      );
32	    }
33	  };
34	
35	  getLoginCredentials = () => {
36	    const accessToken = this.mmkv.getString(
37	      SecureStoreKeys.MATRIX_ACCESS_TOKEN,
38	    );
39	    const userId = this.mmkv.getString(SecureStoreKeys.MATRIX_USER_ID);
40	    const deviceId = this.mmkv.getString(SecureStoreKeys.MATRIX_DEVICE_ID);
41	    const baseUrl = this.mmkv.getString(SecureStoreKeys.MATRIX_BASE_URL);
42	    const refreshToken = this.mmkv.getString(
43	      SecureStoreKeys.MATRIX_REFRESH_TOKEN,
44	    );
45	
46	    if (!accessToken || !userId || !deviceId || !baseUrl) {
47	      return null;
48	    }
49	
50	    return {
51	      accessToken,
52	      userId,
53	      deviceId,
54	      baseUrl,
55	      ...(refreshToken && { refreshToken }),
56	    };
57	  };
58	
59	  clearLoginCredentials = () => {
60	    this.mmkv.delete(SecureStoreKeys.MATRIX_ACCESS_TOKEN);
61	    this.mmkv.delete(SecureStoreKeys.MATRIX_REFRESH_TOKEN);
62	    this.mmkv.delete(SecureStoreKeys.MATRIX_USER_ID);
63	    this.mmkv.delete(SecureStoreKeys.MATRIX_DEVICE_ID);
64	    this.mmkv.delete(SecureStoreKeys.MATRIX_BASE_URL);
65	  };
66	
67	  hasStoredCredentials = () => !!this.getLoginCredentials();
